  await page.locator('#editor').fill('np 10\\nnp 5 / 0');await page.evaluate(()=>window.logomocja.open('np 10\\nnp 5 / 0','2d'));await expect(page.locator('.error-pin')).toHaveCount(1);await expect(page.locator('#error-panel')).toContainText('kolumna 4');await expect(page.locator('#status-detail')).toContainText('1 odcinków');
  await page.locator('#editor').fill('np 20');await expect(page.locator('#error-panel')).toBeHidden();await page.locator('#reset').click();await expect(page.locator('#status-detail')).toContainText('0 odcinków');await expect(page.locator('#editor')).toHaveValue('np 20');
